import{_ as d,o as r,c as e,a2 as o}from"./chunks/framework.CIOzaBgM.js";const p=JSON.parse('{"title":"附录 B 术语表","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/b-glossary.md","filePath":"appendix/b-glossary.md","lastUpdated":1791471399000}'),a={name:"appendix/b-glossary.md"};function n(i,t,l,c,s,_){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="附录-b-术语表" tabindex="-1">附录 B 术语表 <a class="header-anchor" href="#附录-b-术语表" aria-label="Permalink to &quot;附录 B 术语表&quot;">​</a></h1><p>按拼音/字母顺序排列。括号里是英文或代码里的名字，最后是首次详细讲解的章节。</p><table tabindex="0"><thead><tr><th>术语</th><th>解释</th><th>章</th></tr></thead><tbody><tr><td>Agentic RAG</td><td>让模型自己决定检索什么、读什么、什么时候停的 RAG，通常是多轮检索 + 证据充分性判断</td><td>21</td></tr><tr><td>API Key</td><td>给程序调用用的长期令牌，RAGFlow 的格式是 <code>ragflow-</code> 加随机串</td><td>22</td></tr><tr><td>BM25</td><td>经典的全文相关度算法，考虑词频、逆文档频率和文档长度</td><td>11</td></tr><tr><td>chunk（块）</td><td>文档切分后的检索单位，也是写进检索引擎的一行</td><td>3、9</td></tr><tr><td>chunk_method / parser_id</td><td>知识库或文档的&quot;切块方法&quot;（general、book、laws、qa、table、one……），决定用哪个流水线模板</td><td>7</td></tr><tr><td>CJK 二元组（bigram）</td><td>中日韩文本没有空格，把相邻两个字作为一个检索词</td><td>10</td></tr><tr><td>DeepDoc</td><td>RAGFlow 的文档理解模块：版面分析、表格结构识别、OCR</td><td>8</td></tr><tr><td>DSL（流水线描述）</td><td>用 JSON 描述的组件图：每个组件的名字、参数、下游</td><td>7</td></tr><tr><td>embedding（向量）</td><td>把文本映射成定长向量，语义相近的文本向量也相近</td><td>10</td></tr><tr><td>extra_body</td><td>OpenAI 兼容接口里放 RAGFlow 专有参数（如 <code>reference</code>）的对象</td><td>23</td></tr><tr><td>Extractor</td><td>用 LLM 给 chunk 补充关键词、问题、元数据的流水线组件</td><td>18</td></tr><tr><td>fingerprint（指纹）</td><td>内容或版本的摘要值，用来判断源文档有没有变</td><td>25</td></tr><tr><td>FetchRef</td><td>连接器给出的&quot;如何下载&quot;的引用，用于懒下载</td><td>25</td></tr><tr><td>fusion（融合）</td><td>把全文检索和向量检索的结果合成一个排序，如加权求和或 RRF</td><td>13</td></tr><tr><td>hybrid search（混合检索）</td><td>同时使用全文检索和向量检索</td><td>13</td></tr><tr><td>Ingestor</td><td>执行入库任务（解析、切块、向量化、写索引）的进程</td><td>2、6</td></tr><tr><td>JetStream</td><td>NATS 的持久化消息流，RAGFlow 用它投递入库和同步任务</td><td>24</td></tr><tr><td>kNN</td><td>k 近邻：找与查询向量最相近的 k 个向量</td><td>11</td></tr><tr><td>knowledge compilation（知识编译）</td><td>入库时把内容组织成摘要树、图谱、思维导图、Wiki 等更高层的产物</td><td>20</td></tr><tr><td>lease（租约）</td><td>认领任务时写入的&quot;我在处理，有效期到某时刻&quot;，过期即可被他人接手</td><td>24</td></tr><tr><td>MCP</td><td>Model Context Protocol，智能体调用外部工具的协议，基于 JSON-RPC 2.0</td><td>23</td></tr><tr><td>metadata filter（元数据过滤）</td><td>按文档属性（如型号、日期）缩小检索范围的硬条件</td><td>19</td></tr><tr><td>min_match / minimum_should_match</td><td>全文查询中至少要命中的检索词比例，RAGFlow 默认 0.3，重试时降到 0.1</td><td>12</td></tr><tr><td>mock provider</td><td>本书中确定性的假模型（假 embedding 用特征哈希，假 LLM 从上下文里摘句子），让一切离线可跑</td><td>0</td></tr><tr><td>pagerank（文档权重）</td><td>RAGFlow 里人为设置的知识库权重，加到排序分数上</td><td>13</td></tr><tr><td>pipeline（流水线）</td><td>入库的一串组件：File → Parser → Chunker → Extractor → Tokenizer → …</td><td>7</td></tr><tr><td>poison message（毒消息）</td><td>每次处理都会让 worker 失败或崩溃的任务，需要投递次数上限</td><td>24</td></tr><tr><td>prune（删除同步）</td><td>根据源的完整清单，删除知识库里源已不存在的文档</td><td>25</td></tr><tr><td>RAG</td><td>Retrieval-Augmented Generation，先检索再让模型基于检索结果生成</td><td>1</td></tr><tr><td>RAPTOR</td><td>递归摘要树：聚类 → 摘要 → 再聚类，所有层都进入索引</td><td>20</td></tr><tr><td>reasoning level（思考等级）</td><td>RAGFlow 聊天的检索策略开关：0 普通、1~4 研究循环、5 smart-reasoning</td><td>21</td></tr><tr><td>reference（引用）</td><td>回答所依据的 chunk 列表，回答中用 <code>[ID:n]</code> 指向它们</td><td>16</td></tr><tr><td>rerank（重排）</td><td>用专门的重排模型对候选重新打分</td><td>13</td></tr><tr><td>SCA</td><td>Sufficient Context Agent，RAGFlow 研究循环里判断&quot;证据是否足够&quot;的审查步骤</td><td>21</td></tr><tr><td>scripted_sim</td><td>RAGFlow 在 ES 映射里给 <code>*_tks</code> 字段定义的打分：只看是否出现，不做长度归一</td><td>11</td></tr><tr><td>SourceID</td><td>连接器内稳定、唯一的源文档 id，同步与删除的依据</td><td>25</td></tr><tr><td>SSE</td><td>Server-Sent Events，基于 HTTP 的单向流，用来流式返回回答</td><td>16</td></tr><tr><td>Syncer</td><td>执行数据源同步的进程</td><td>25</td></tr><tr><td>tag（标签）</td><td>RAGFlow 的软排序特征：问题与 chunk 标签越相似，分数加得越多</td><td>19</td></tr><tr><td>tenant（租户）</td><td>数据的归属单位；RAGFlow 中租户 id 等于其所有者的用户 id</td><td>22</td></tr><tr><td>term weight（词权重）</td><td>每个检索词的重要性，基于 IDF 和词性等</td><td>12</td></tr><tr><td>threshold（相似度阈值）</td><td>低于它的 chunk 不返回，RAGFlow 默认 0.2</td><td>13</td></tr><tr><td>tokenizer（分词）</td><td>把文本切成检索词；RAGFlow 生成粗粒度 <code>*_ltks</code> 和细粒度 <code>*_sm_ltks</code></td><td>10</td></tr><tr><td>top_k / top_n</td><td>向量检索的候选数 / 最终返回或送入提示词的块数</td><td>13、15</td></tr><tr><td>vector_similarity_weight</td><td>混合打分中向量相似度的权重，全文权重为 1 减去它，默认 0.3</td><td>13</td></tr><tr><td>watershed</td><td>RAGFlow RAPTOR 的分段算法：按文档顺序，在相邻向量相似度低的地方切开</td><td>20</td></tr><tr><td>WAL</td><td>SQLite 的预写日志模式，允许读写并发</td><td>24、26</td></tr><tr><td>两阶段检索</td><td>第一阶段由引擎召回较多候选，第二阶段在应用里重新打分、过滤、分页</td><td>13</td></tr><tr><td>多轮改写（refine）</td><td>用 LLM 把依赖上下文的追问改写成独立的问题</td><td>15</td></tr><tr><td>断点续传（checkpoint）</td><td>同步任务每批提交后保存的位置，失败重跑时从这里继续</td><td>25</td></tr><tr><td>哨兵值（sentinel）</td><td>一个不可能存在的值（如文档 id <code>&quot;-999&quot;</code>），用来表达&quot;空集合&quot;而不被当成&quot;不限制&quot;</td><td>19</td></tr><tr><td>重投递（redelivery）</td><td>任务没有被确认（进程死了或主动放弃）时，再交给其他 worker</td><td>24</td></tr></tbody></table>',3)])])}const u=d(a,[["render",n]]);export{p as __pageData,u as default};
